cssCode:
.radial-wrap { position: relative; width: 60px; height: 60px; }
.radial-main {
  width: 60px; height: 60px; border-radius: 50%;
  background: #ff007f; color: #fff; font-size: 30px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; z-index: 10; position: absolute;
  box-shadow: 0 5px 15px rgba(255,0,127,0.4); transition: transform 0.3s;
}
.radial-wrap.open .radial-main { transform: rotate(45deg); }
.radial-item {
  width: 40px; height: 40px; border-radius: 50%; background: #222;
  color: #00ffcc; display: flex; align-items: center; justify-content: center;
  position: absolute; top: 10px; left: 10px; z-index: 5;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); opacity: 0;
  border: 1px solid rgba(0,255,204,0.3); font-family: sans-serif;
}
.radial-wrap.open .radial-item { opacity: 1; }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'radial-wrap';

const mainBtn = document.createElement('div');
mainBtn.className = 'radial-main';
mainBtn.innerText = '+';

const icons = ['A', 'B', 'C', 'D'];
const items = icons.map((txt, index) => {
  const item = document.createElement('div');
  item.className = 'radial-item';
  item.innerText = txt;
  wrap.appendChild(item);
  return { el: item, angle: (index * (360 / icons.length)) * (Math.PI / 180) };
});

wrap.appendChild(mainBtn);
c.appendChild(wrap);

mainBtn.addEventListener('click', () => {
  const isOpen = wrap.classList.toggle('open');
  items.forEach(item => {
    if(isOpen) {
      const radius = 70;
      const x = Math.cos(item.angle) * radius;
      const y = Math.sin(item.angle) * radius;
      item.el.style.transform = `translate(${x}px, ${y}px)`;
    } else {
      item.el.style.transform = `translate(0px, 0px)`;
    }
  });
});
